/**
 * lib/imzalar.ts
 *
 * Evraklarda kullanilan sabit gorseller (base64 data-URI).
 * Yazdirma aninda ve Blob URL ile acildiginda ag beklemesi / yol sorunu
 * olmadan %100 gorunmesi icin gorseller HTML'e dogrudan gomulur
 * (Supabase Storage / public klasor yerine).
 *
 * IMZA_HARUN  : Kase + imza birlikte. Commercial Invoice, Packing List ve
 *               Fumigation (sol/hazirlayan) icin kullanilir.
 * IMZA_CIGDEM : Fumigation Operator imzasi. Fumigation (sag) icin kullanilir.
 * LOGO_UNEX   : Unex firma logosu. Her uc evrakta da (header) kullanilir.
 *               NOT: Blob URL ile acilan sayfalarda "/images/logo.png" gibi
 *               goreli yollar cozulemedigi icin logo da base64 olarak gomulur.
 *
 * Gorseller seffaf arka planli PNG'dir.
 */

export const IMZA_HARUN = "data:image/png;base64,";

export const IMZA_CIGDEM = "data:image/png;base64,";

export const LOGO_UNEX = "data:image/png;base64,";